using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Threading;
using RenoDXMfgUnlocker;

internal static class Rc2UxChecks
{
    public static IEnumerable<(string Name,Action Run)> All(){
        yield return("rc2 executable labels distinguish same filenames and preserve exact Unicode paths",Labels);
        yield return("rc2 executable selection remains explicit and resets when candidate list changes",Selection);
        yield return("rc2 executable long paths wrap in materialized dark keyboard-accessible rows",Layout);
        yield return("rc2 executable Enter confirms only an explicitly selected candidate",KeyboardConfirmation);
        yield return("rc2 generation presenter derives exact saved pending and default values from schema",Presentation);
        yield return("rc2 generation information updates with selection without writes or false dirty state",GenerationUi);
        yield return("rc2 generation Discard Reload and older schemas retain existing restrictions",DiscardReload);
        yield return("rc2 About cards cover current capabilities limitations and original attribution",About);
        yield return("rc2 all new descriptions have six-language resources and preserve technical values",Localization);
    }
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private const BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
    private static object? Call(object o,string name,params object?[] args)=>o.GetType().GetMethod(name,Flags)!.Invoke(o,args);
    private static string[] Paths()=>new[]{@"C:\isolated\Counter-Strike 2\game\bin\win64\cs2.exe",@"C:\isolated\Counter-Strike 2\game\csgo\bin\legacy\cs2.exe",@"C:\ізольована\"+new string('x',120)+@"\sous-dossier\"+new string('e',100)+".exe"};
    private static void Labels(){var rows=Paths().Select(p=>new ExecutableChoice(p)).ToArray();Check(rows[0].FileName==rows[1].FileName&&rows[0].DirectoryPath!=rows[1].DirectoryPath,"Same-name candidates ambiguous");for(var i=0;i<rows.Length;i++)Check(rows[i].FullPath==Paths()[i]&&rows[i].ToString()==Paths()[i],"Opaque path changed");foreach(var area in new[]{new Size(1440,900),new Size(640,480),new Size(420,300)}){var size=ExecutableSelectionView.DialogSize(area);Check(size.Width<=area.Width-32&&size.Height<=area.Height-32,"Dialog ignores work area / DPI logical bounds");}}
    private static void Selection()=>WpfCheckHost.Run(()=>{var all=Paths();var view=new ExecutableSelectionView("Own game",all,()=>all.Reverse().ToArray());string? confirmed=null;view.Confirmed+=p=>confirmed=p;Check(view.SelectedPath is null&&!view.Choose.IsEnabled,"Auto-selected candidate");view.Choose.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(confirmed is null,"Disabled selection confirmed");view.Candidates.SelectedIndex=1;Check(confirmed is null,"Navigation confirmed without consent");view.Choose.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(confirmed==all[1],"Wrong exact candidate confirmed");view.ShowAll.IsChecked=true;Check(view.SelectedPath is null&&!view.Choose.IsEnabled,"Show All retained stale choice");view.Candidates.SelectedIndex=0;view.ShowAll.IsChecked=false;Check(view.SelectedPath is null&&!view.Choose.IsEnabled,"Filtered list retained stale choice");});
    private static IEnumerable<DependencyObject> Visual(DependencyObject root){for(var i=0;i<VisualTreeHelper.GetChildrenCount(root);i++){var c=VisualTreeHelper.GetChild(root,i);yield return c;foreach(var n in Visual(c))yield return n;}}
    private static void Layout()=>WpfCheckHost.Run(()=>{var view=new ExecutableSelectionView("Own",Paths(),Paths);view.Measure(new Size(440,400));view.Arrange(new Rect(0,0,440,400));view.UpdateLayout();Check(ScrollViewer.GetHorizontalScrollBarVisibility(view.Candidates)==ScrollBarVisibility.Disabled&&view.Candidates.Focusable,"Horizontal scrolling or missing keyboard navigation");for(var i=0;i<2;i++){var row=(ListBoxItem?)view.Candidates.ItemContainerGenerator.ContainerFromIndex(i);Check(row is not null,"Row template not materialized");Check(row!.ToolTip as string==Paths()[i]&&AutomationProperties.GetHelpText(row)==Paths()[i],"Full tooltip / accessible path lost");var text=Visual(row).OfType<TextBlock>().Where(t=>t.Text.Length>0).ToArray();Check(text.Length>=2&&text.All(t=>t.TextWrapping==TextWrapping.Wrap),"Labels remain single-line trimmed");Check(row.Background is SolidColorBrush brush&&brush.Color.R<80&&row.ActualWidth<=440,"Theme or row bounds regressed");}});
    private sealed class KeySource:PresentationSource {public override Visual RootVisual{get;set;}=new DrawingVisual();public override bool IsDisposed=>false;protected override CompositionTarget GetCompositionTargetCore()=>null!;}
    private static void KeyboardConfirmation()=>WpfCheckHost.Run(()=>{var view=new ExecutableSelectionView("Own",Paths(),Paths);var source=new KeySource();string? selected=null;view.Confirmed+=p=>selected=p;void Enter()=>view.Candidates.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,source,0,Key.Enter){RoutedEvent=Keyboard.KeyDownEvent});Enter();Check(selected is null,"Enter selected a default candidate");view.Candidates.SelectedIndex=1;Enter();Check(selected==Paths()[1],"Keyboard confirmation did not preserve exact path");});
    private static GenerationMethodPresentation Info(Rc1SettingsChecks.Fixture f)=>(GenerationMethodPresentation)((Border)((StackPanel)f.Window.FindName("GenerationModePanel")).Children[1]).Tag;
    private static void Presentation(){var root=Path.Combine(Path.GetTempPath(),"RenoDX-RC2",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var path=Path.Combine(root,"MFGAdaUnlock.ini");var service=new MfgUnlockSettingsService(true);var defaults=service.Load(path,root,"1.8.0.0");Dictionary<string,string?> Values(string backend,string xmx)=>new(){{"Selected",backend},{"XmxGenerator",xmx}};var unchanged=GenerationMethodPresenter.Describe(defaults,Values("DLSSG","0"))!;Check(!unchanged.Pending&&unchanged.DefaultsInUse&&unchanged.SavedMethod=="NVIDIA DLSS-G","Defaults treated as saved changes");var xmx=GenerationMethodPresenter.Describe(defaults,Values("DLSSG","1"))!;Check(xmx.Pending&&xmx.SelectedMethod==defaults.Settings.Single(s=>s.Definition.Key=="XmxGenerator").Definition.Label&&xmx.IniValues.Contains("[Backend] Selected: DLSSG → DLSSG")&&xmx.IniValues.Contains("[DLSSG] XmxGenerator: 0 → 1"),"XMX schema mapping drifted");Check(GenerationMethodPresenter.Describe(defaults,Values("Fake","0")) is null,"Invalid values described as valid");Check(!File.Exists(path),"Presenter wrote configuration");foreach(var v in new[]{"1.6.0.0","1.7.0.0","1.8.0-beta.1"})Check(GenerationMethodPresenter.Describe(service.Load(path,root,v),Values("DLSSG","1")) is null,"Older/future schema suggests XMX");}
    private static void GenerationUi()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();var hashes=f.Hashes();foreach(var mode in new[]{"XMX","XeMFG","DLSSG"}){Call(f.Window,"SelectGenerationMethod",mode);var info=Info(f);Check(info.SavedMethod=="NVIDIA DLSS-G"&&info.Pending==(mode!="DLSSG"),"Saved / pending method incorrect");Check(mode!="XMX"||info.Description.Contains("D3D12")&&info.Description.Contains("native DLSS"),"XMX requirements missing");Call(f.Window,"SelectGenerationMethod",mode);Check(Info(f)==info,"Selecting same mode creates false pending change");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Selection wrote files");}});
    private static void DiscardReload()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();Call(f.Window,"SelectGenerationMethod","XMX");f.Select(MfgSettingsCategory.Other);((Button)f.Window.FindName("MfgSettingsDiscardButton")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!Info(f).Pending&&f.Value("XmxGenerator")=="0","Discard did not refresh information");Call(f.Window,"SelectGenerationMethod","XeMFG");var hashes=f.Hashes();var task=(Task)Call(f.Window,"LoadMfgSettingsAsync")!;var until=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&until.Elapsed<TimeSpan.FromSeconds(8)){Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Thread.Sleep(1);}Check(task.IsCompleted,"Reload timeout");task.GetAwaiter().GetResult();Check(((StackPanel)f.Window.FindName("GenerationModePanel")).Visibility==Visibility.Collapsed&&!((Button)f.Window.FindName("MfgSettingsSaveButton")).IsEnabled,"Reload trusted synthetic addon or left mode information editable");Check(hashes.All(p=>f.Hashes()[p.Key]==p.Value),"Discard / Reload wrote configuration");});
    private static IEnumerable<DependencyObject> Logical(DependencyObject root){foreach(var c in LogicalTreeHelper.GetChildren(root).OfType<DependencyObject>()){yield return c;foreach(var n in Logical(c))yield return n;}}
    private static void About()=>WpfCheckHost.Run(()=>{var w=new MainWindow();try{var cards=(Panel)w.FindName("AboutFeaturesPanel");Check(cards.Children.Count==12,"Current feature cards missing");var text=string.Join("\n",AboutFeatureCatalog.Features.SelectMany(f=>new[]{f.Item1,f.Item2}));foreach(var needle in new[]{"Manual NVIDIA","Verified Update","Add / Replace / No Change","XeMFG / XeLL","ReShade","outside managed Restore","1.8.0 / XMX","General / Advanced / Other","Runtime Diagnostics","Authenticated transactions","Official SDK","Six interface languages"})Check(text.Contains(needle),"About omits "+needle);var labels=Logical((DependencyObject)w.FindName("AboutPage")).OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(labels.Contains("ExiZz")&&labels.Contains("Mateus Jorge / mavismmg"),"Attribution lost");Check(text.Contains("configuration-specific")&&text.Contains("installed files from loaded or active"),"Compatibility distinction missing");}finally{w.Close();}});
    private static void Localization()=>WpfCheckHost.Run(()=>{using var f=new Rc1SettingsChecks.Fixture();Call(f.Window,"SelectGenerationMethod","XMX");var l=LocalizedPresentation.Language;try{Check(l.ValidateCatalogs().Count==0,"Catalog integrity");foreach(var c in UiLocalization.Cultures){l.SetCulture(c,false);foreach(var feature in AboutFeatureCatalog.Features)foreach(var value in new[]{feature.Item1,feature.Item2})Check(l.GetCatalog(c).ContainsKey(value),"Missing About resource "+c+" / "+value);var info=Info(f);var panel=((Border)((StackPanel)f.Window.FindName("GenerationModePanel")).Children[1]);var texts=Logical(panel).OfType<TextBlock>().Select(t=>t.Text).ToArray();Check(texts.Contains(l.Format("Selected method: {0}",l.Lookup(info.SelectedMethod)))&&texts.Contains(l.Format("Saved method: {0}",l.Lookup(info.SavedMethod)))&&texts.Contains(l.Lookup("Unsaved configuration change")),"Late information not translated");Check(texts.Any(t=>t.Contains("[Backend] Selected: DLSSG → DLSSG")&&t.Contains("[DLSSG] XmxGenerator: 0 → 1")),"Technical keys / values localized");Check(f.Value("XmxGenerator")=="1"&&TechnicalVersionDisplay.Format("1,8,0,0")=="1.8.0.0","Language changed configuration or versions");}}finally{l.SetCulture("en-US",false);}});
}

